156→func readAPIError(resp *http.Response, action string) error {
157→	apiErr, err := readAPIErrorResponse(resp)
158→	if err == nil {
159→		return fmt.Errorf("%s: %s", action, apiErr.Error)
160→	}
161→	return fmt.Errorf("%s: %w", action, err)
162→}
